with gaps as (select *, case when lag(paid_at) over (partition by order_id order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by order_id order by paid_at, id) + interval '90' day then 1 else 0 end as is_new_session from payments) select id, order_id, amount, paid_at, sum(is_new_session) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as island_id from gaps
